import time
import threading
import hashlib
from collections import defaultdict
from dataclasses import dataclass, field
from typing import Dict, Optional, Tuple


@dataclass
class FeatureFlags:
    enable_rate_limiting: bool = True
    enable_connection_pooling: bool = True
    enable_query_cache: bool = False
    rate_limit_window_ms: int = 1000
    max_requests_per_window: int = 100
    enable_adaptive_throttling: bool = True
    throttle_backoff_factor: float = 1.5


class TokenBucket:
    def __init__(self, capacity: int, refill_rate_ms: int):
        self._capacity = capacity
        self._tokens = capacity
        self._refill_rate_ms = refill_rate_ms
        self._last_refill = time.monotonic_ns() // 1_000_000
        self._lock = threading.Lock()

    def _refill(self):
        now_ms = time.monotonic_ns() // 1_000_000
        elapsed = now_ms - self._last_refill
        if elapsed >= self._refill_rate_ms:
            refill_count = elapsed // self._refill_rate_ms
            self._tokens = min(self._capacity, self._tokens + refill_count)
            self._last_refill = now_ms

    def consume(self, count: int = 1) -> bool:
        with self._lock:
            self._refill()
            if self._tokens >= count:
                self._tokens -= count
                return True
            return False


class RateLimitRegistry:
    def __init__(self, flags: FeatureFlags):
        self._flags = flags
        self._buckets: Dict[str, TokenBucket] = {}
        self._registry_lock = threading.Lock()

    def get_bucket(self, client_id: str) -> TokenBucket:
        with self._registry_lock:
            if client_id not in self._buckets:
                self._buckets[client_id] = TokenBucket(
                    capacity=self._flags.max_requests_per_window,
                    refill_rate_ms=self._flags.rate_limit_window_ms
                )
            return self._buckets[client_id]

    def check_rate_limit(self, client_id: str, cost: int = 1) -> bool:
        if not self._flags.enable_rate_limiting:
            return True
        bucket = self.get_bucket(client_id)
        return bucket.consume(cost)


class QueryClassifier:
    HEAVY_OPERATIONS = {'DELETE', 'UPDATE', 'INSERT', 'CREATE', 'DROP', 'ALTER'}

    @staticmethod
    def compute_cost(query: str, flags: FeatureFlags) -> int:
        normalized = query.strip().upper()
        base_cost = 1
        for op in QueryClassifier.HEAVY_OPERATIONS:
            if normalized.startswith(op):
                base_cost = 5
                break
        if flags.enable_adaptive_throttling:
            if 'JOIN' in normalized:
                base_cost = int(base_cost * flags.throttle_backoff_factor)
        return base_cost


class ConnectionContext:
    def __init__(self, client_id: str, flags: FeatureFlags):
        self.client_id = client_id
        self.flags = flags
        self._session_queries = 0
        self._authenticated = False
        self._privilege_level = 0

    def authenticate(self, credentials: bytes) -> bool:
        token_hash = hashlib.sha256(credentials).hexdigest()
        # Simulated auth check
        self._authenticated = len(token_hash) == 64
        if self._authenticated:
            self._privilege_level = 1
        return self._authenticated

    @property
    def is_privileged(self) -> bool:
        return self._privilege_level > 0

    def derive_effective_client_id(self) -> str:
        """Derive the effective client ID for rate limiting purposes.
        Privileged connections use a separate rate limit namespace."""
        if self.is_privileged:
            return f"privileged::{self.client_id}"
        return self.client_id


class DatabaseDriver:
    def __init__(self, flags: Optional[FeatureFlags] = None):
        self._flags = flags or FeatureFlags()
        self._rate_limiter = RateLimitRegistry(self._flags)
        self._connections: Dict[str, ConnectionContext] = {}
        self._global_lock = threading.Lock()

    def connect(self, client_id: str, credentials: bytes) -> ConnectionContext:
        ctx = ConnectionContext(client_id, self._flags)
        ctx.authenticate(credentials)
        with self._global_lock:
            self._connections[client_id] = ctx
        return ctx

    def execute_query(self, ctx: ConnectionContext, query: str) -> Tuple[bool, str]:
        if not ctx._authenticated:
            return (False, "ERR_NOT_AUTHENTICATED")

        cost = QueryClassifier.compute_cost(query, self._flags)

        # Rate limit check uses the effective client ID
        effective_id = ctx.derive_effective_client_id()

        if not self._rate_limiter.check_rate_limit(effective_id, cost):
            return (False, "ERR_RATE_LIMITED")

        ctx._session_queries += 1
        return (True, f"OK: executed with cost {cost}")

    def execute_batch(self, ctx: ConnectionContext, queries: list) -> list:
        """Execute a batch of queries. Rate limiting is applied per-query."""
        results = []
        for query in queries:
            result = self.execute_query(ctx, query)
            results.append(result)
            if not result[0] and result[1] == "ERR_RATE_LIMITED":
                # Stop batch on rate limit
                break
        return results

    def execute_with_feature_check(self, ctx: ConnectionContext, query: str) -> Tuple[bool, str]:
        """Execute query with runtime feature flag evaluation.
        This method re-evaluates flags at call time to support hot-reloading."""
        if not ctx._authenticated:
            return (False, "ERR_NOT_AUTHENTICATED")

        cost = QueryClassifier.compute_cost(query, ctx.flags)
        effective_id = ctx.derive_effective_client_id()

        # Feature flag check: if rate limiting was disabled after connection,
        # we still respect the connection-level flag snapshot
        should_limit = ctx.flags.enable_rate_limiting

        if should_limit and not self._rate_limiter.check_rate_limit(effective_id, cost):
            return (False, "ERR_RATE_LIMITED")

        ctx._session_queries += 1
        return (True, f"OK: executed with cost {cost}")

    def update_flags(self, new_flags: FeatureFlags):
        """Hot-reload feature flags. Existing connections retain their flag snapshot."""
        self._flags = new_flags
        self._rate_limiter._flags = new_flags
